svg.script:
// --- Global State ---
let player = { x: 0, y: 1.6, z: 0, yaw: 0, pitch: 0, walkPhase: 0, speed: 0, vy: 0, fwd: 0, strafe: 0 };
let cam = { x: 0, y: 1.6, z: 0, yaw: 0, pitch: 0 };
let isThirdPerson = false;
let keys = {};
let touchControls = { up: 0, down: 0, left: 0, right: 0 };
let fireFlash = 0;
let lastTime = 0;
let scene, atonRaG, ui, floorJade, floorYellow;
let prevGamepad = { view: false };

// Combat State
let enemies = [];
let bullets = [];
let particles = [];

// --- Pre-Allocated Memory Pools ---
let vertPool = new Array(10000);
for(let i=0; i<10000; i++) vertPool[i] = { x:0, y:0, z:0 };
let vertIdx = 0;

let invaderVerts = new Array(81);
for(let i=0; i<81; i++) invaderVerts[i] = { fx:0, fy:0, fz:0, bx:0, by:0, bz:0 };

let pathPool = [], circlePool = [], rectPool = [];

function getPoolEl(pool, tag, parent, idx) {
  let el;
  if (idx < pool.length) {
    el = pool[idx];
  } else {
    el = document.createElementNS("http://www.w3.org/2000/svg", tag);
    pool.push(el);
  }
  parent.appendChild(el);
  el.style.display = '';
  return el;
}

// --- 2D Inverse Kinematics Math ---
function ik2D(ax, ay, len1, len2, tx, ty, bend) {
  let dx = tx - ax, dy = ty - ay;
  let dist = Math.hypot(dx, dy);
  let maxDist = len1 + len2 - 0.01;
  if (dist > maxDist) {
    dist = maxDist;
    dx = (dx / dist) * maxDist;
    dy = (dy / dist) * maxDist;
    tx = ax + dx;
    ty = ay + dy;
  }
  let minDist = Math.abs(len1 - len2) + 0.01;
  if (dist < minDist) dist = minDist;

  let cosA = (len1*len1 + dist*dist - len2*len2) / (2 * len1 * dist);
  cosA = Math.max(-1, Math.min(1, cosA));
  let angleA = Math.acos(cosA);

  let baseAngle = Math.atan2(dy, dx);
  let jointAngle = baseAngle + bend * angleA;

  let jx = ax + Math.cos(jointAngle) * len1;
  let jy = ay + Math.sin(jointAngle) * len1;

  return { jx, jy, tx, ty };
}

// Helper to generate solid blocky limbs for Aton Ra
function makeLimb(x1, y1, x2, y2, w, color) {
  let angle = Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI;
  let len = Math.hypot(x2 - x1, y2 - y1);
  let str = `<g transform="translate(${x1}, ${y1}) rotate(${angle})">`;
  str += `<rect x="0" y="${-w/2}" width="${len}" height="${w}" fill="${color}" rx="${w*0.2}"/>`;
  str += `</g>`;
  return str;
}

// --- Initialization ---
function initGame() {
  scene = document.getElementById('entityLayer');
  atonRaG = document.getElementById('atonRa');
  floorJade = document.getElementById('floorJade');
  floorYellow = document.getElementById('floorYellow');
  let svgEl = document.querySelector('svg');

  for(let i=0; i<20; i++) {
    enemies.push({
      x: -12 + (i % 5) * 6,
      y: 1.0,
      z: 10 + Math.floor(i / 5) * 5, 
      fireCD: Math.random() * 300 + 100,
      movePhase: i * 0.5
    });
  }

  document.addEventListener('keydown', (e) => {
    keys[e.key.toLowerCase()] = true;
    if (e.key.toLowerCase() === 'v') toggleView();
    if (e.key === ' ') fire();
    if (['w','a','s','d',' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase())) e.preventDefault();
  });
  document.addEventListener('keyup', (e) => { keys[e.key.toLowerCase()] = false; });

  bindTouch('btnUp', () => touchControls.up = 1, () => touchControls.up = 0);
  bindTouch('btnDown', () => touchControls.down = 1, () => touchControls.down = 0);
  bindTouch('btnLeft', () => touchControls.left = 1, () => touchControls.left = 0);
  bindTouch('btnRight', () => touchControls.right = 1, () => touchControls.right = 0);
  bindTouch('btnFire', () => fire(), () => {});
  bindTouch('btnView', () => toggleView(), () => {});

  document.addEventListener('mousemove', (e) => {
    if (document.pointerLockElement) {
      player.yaw += e.movementX * 0.002;
      player.pitch -= e.movementY * 0.002;
      player.pitch = Math.max(-1.2, Math.min(1.2, player.pitch));
    }
  });

  svgEl.addEventListener('click', (e) => {
    if (e.target.id.startsWith('btn')) return;
    if (!document.pointerLockElement) svgEl.requestPointerLock();
  });

  requestAnimationFrame(gameLoop);
}

function bindTouch(id, onDown, onUp) {
  let el = document.getElementById(id);
  if (!el) return;
  el.addEventListener('mousedown', (e) => { e.preventDefault(); onDown(); });
  el.addEventListener('mouseup', (e) => { e.preventDefault(); onUp(); });
  el.addEventListener('touchstart', (e) => { e.preventDefault(); onDown(); }, { passive: false });
  el.addEventListener('touchend', (e) => { e.preventDefault(); onUp(); }, { passive: false });
}

function toggleView() { isThirdPerson = !isThirdPerson; }
function fire() {
  if (fireFlash <= 0) {
    fireFlash = 10;
    let dirX = Math.sin(player.yaw) * Math.cos(player.pitch);
    let dirY = -Math.sin(player.pitch);
    let dirZ = Math.cos(player.yaw) * Math.cos(player.pitch);
    bullets.push({
      x: player.x, y: player.y + 0.4, z: player.z,
      dx: dirX * 0.6, dy: dirY * 0.6, dz: dirZ * 0.6,
      color: 'yellow', life: 60, owner: 'player'
    });
  }
}

function gameLoop(timestamp) {
  let dt = (timestamp - lastTime) / 16.66; 
  if (dt > 3) dt = 3; 
  lastTime = timestamp;
  update(dt);
  render();
  requestAnimationFrame(gameLoop);
}

function update(dt) {
  let ix = 0, iy = 0, turn = 0, look = 0;

  if (keys['w']) iy += 1; if (keys['s']) iy -= 1;
  if (keys['a']) ix -= 1; if (keys['d']) ix += 1;
  if (keys['q']) turn -= 0.05; if (keys['e']) turn += 0.05;
  if (keys['arrowup']) look += 0.03; if (keys['arrowdown']) look -= 0.03;

  iy += touchControls.up - touchControls.down;
  ix += touchControls.right - touchControls.left;

  let gp = navigator.getGamepads()[0];
  if (gp) {
    let lx = gp.axes[0] || 0, ly = gp.axes[1] || 0;
    let rx = gp.axes[2] || 0, ry = gp.axes[3] || 0;
    if (Math.abs(lx) < 0.15) lx = 0; if (Math.abs(ly) < 0.15) ly = 0;
    if (Math.abs(rx) < 0.15) rx = 0; if (Math.abs(ry) < 0.15) ry = 0;
    iy -= ly; ix += lx;
    turn += rx * 0.05; look -= ry * 0.03;
    if (gp.buttons[12] && gp.buttons[12].pressed) iy += 1;
    if (gp.buttons[13] && gp.buttons[13].pressed) iy -= 1;
    if (gp.buttons[14] && gp.buttons[14].pressed) ix -= 1;
    if (gp.buttons[15] && gp.buttons[15].pressed) ix += 1;

    // Fire with A (0), Right Bumper (5), or Right Trigger (7)
    if ((gp.buttons[0] && gp.buttons[0].pressed) || 
        (gp.buttons[5] && gp.buttons[5].pressed) || 
        (gp.buttons[7] && gp.buttons[7].pressed)) {
      fire(); 
    }

    let yPressed = gp.buttons[3] && gp.buttons[3].pressed;
    if (yPressed && !prevGamepad.view) toggleView();
    prevGamepad.view = yPressed;
  }

  player.yaw += turn * dt;
  player.pitch += look * dt;
  player.pitch = Math.max(-1.2, Math.min(1.2, player.pitch));

  let mag = Math.sqrt(ix*ix + iy*iy);
  if (mag > 1) { ix /= mag; iy /= mag; }
  let speed = 0.15;
  let forward = [Math.sin(player.yaw), Math.cos(player.yaw)];
  let right = [Math.cos(player.yaw), -Math.sin(player.yaw)];
  let vx = forward[0] * iy + right[0] * ix;
  let vz = forward[1] * iy + right[1] * ix;
  player.x += vx * speed * dt;
  player.z += vz * speed * dt;
  player.speed = Math.sqrt(vx*vx + vz*vz);

  player.fwd = iy;
  player.strafe = ix;

  if (player.speed > 0.01) player.walkPhase += 0.2 * dt;
  else player.walkPhase += 0.02 * dt; 

  if (isThirdPerson) {
    let camDist = 4;
    cam.x = player.x - Math.sin(player.yaw) * camDist;
    cam.z = player.z - Math.cos(player.yaw) * camDist;
    cam.y = player.y + 1.0;
    cam.yaw = player.yaw;
    cam.pitch = player.pitch - 0.2;
  } else {
    cam.x = player.x; cam.y = player.y; cam.z = player.z;
    cam.yaw = player.yaw; cam.pitch = player.pitch;
  }

  if (fireFlash > 0) fireFlash -= dt;

  let activeEnemyBullets = 0;
  for(let b of bullets) if(b.owner === 'enemy') activeEnemyBullets++;

  for(let e of enemies) {
    e.movePhase += 0.02 * dt;
    e.x += Math.sin(e.movePhase) * 0.02 * dt;
    e.z -= 0.005 * dt; 
    e.fireCD -= dt;
    if(e.fireCD <= 0) {
      e.fireCD = Math.random() * 300 + 150;
      if(activeEnemyBullets < 5) {
        activeEnemyBullets++;
        let dx = player.x - e.x, dy = (player.y+0.4) - e.y, dz = player.z - e.z;
        let dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
        bullets.push({
          x: e.x, y: e.y, z: e.z,
          dx: (dx/dist) * 0.3, dy: (dy/dist) * 0.3, dz: (dz/dist) * 0.3,
          color: 'red', life: 120, owner: 'enemy'
        });
      }
    }
  }

  for(let i=bullets.length-1; i>=0; i--) {
    let b = bullets[i];
    b.x += b.dx * dt; b.y += b.dy * dt; b.z += b.dz * dt;
    b.life -= dt;
    if(b.life <= 0) { bullets.splice(i,1); continue; }

    if(b.owner == 'player') {
      for(let j=enemies.length-1; j>=0; j--) {
        let e = enemies[j];
        let dx = b.x - e.x, dy = b.y - e.y, dz = b.z - e.z;
        if(dx*dx + dy*dy + dz*dz < 6.0) { 
          spawnParticles(e.x, e.y, e.z, '#90EE90');
          enemies.splice(j, 1);
          bullets.splice(i, 1);
          break;
        }
      }
    } else if(b.owner == 'enemy') {
      let dx = b.x - player.x, dy = b.y - (player.y+0.4), dz = b.z - player.z;
      if(dx*dx + dy*dy + dz*dz < 0.8) {
        spawnParticles(player.x, player.y+0.4, player.z, '#FF0000');
        bullets.splice(i, 1);
      }
    }
  }

  for(let i=particles.length-1; i>=0; i--) {
    let p = particles[i];
    p.x += p.dx * dt; p.y += p.dy * dt; p.z += p.dz * dt;
    p.life -= dt;
    if(p.life <= 0) particles.splice(i,1);
  }
}

function spawnParticles(x, y, z, color) {
  for(let i=0; i<10; i++) { 
    particles.push({
      x: x, y: y, z: z,
      dx: (Math.random()-0.5) * 0.4,
      dy: (Math.random()-0.5) * 0.4,
      dz: (Math.random()-0.5) * 0.4,
      life: 30, color: color
    });
  }
}

function project(x, y, z) {
  let dx = x - cam.x, dy = y - cam.y, dz = z - cam.z;
  let cosY = Math.cos(cam.yaw), sinY = Math.sin(cam.yaw);
  let rx = dx * cosY + dz * sinY;
  let rz = -dx * sinY + dz * cosY;
  let ry = dy;
  let cosP = Math.cos(cam.pitch), sinP = Math.sin(cam.pitch);
  let ry2 = ry * cosP - rz * sinP;
  let rz2 = ry * sinP + rz * cosP;
  if (rz2 <= 0.1) return null;

  let v = vertPool[vertIdx++];
  v.x = (rx / rz2) * 400 + 400;
  v.y = (-ry2 / rz2) * 400 + 300;
  v.z = rz2;
  return v;
}

function render() {
  vertIdx = 0; 
  let R = 2.0;

  let pHexX = Math.round(cam.x / (1.5 * R));
  let pHexZ = Math.round(cam.z / (Math.sqrt(3) * R));
  let jadeArr = [], yellowArr = [];

  for (let i = pHexX - 8; i <= pHexX + 8; i++) {
    for (let j = pHexZ - 8; j <= pHexZ + 8; j++) {
      let cx = i * 1.5 * R;
      let cz = j * Math.sqrt(3) * R + (i % 2) * (Math.sqrt(3) * R / 2);

      let v0 = project(cx + R, 0, cz);
      let v1 = project(cx + R*0.5, 0, cz + R*0.866);
      let v2 = project(cx - R*0.5, 0, cz + R*0.866);
      let v3 = project(cx - R, 0, cz);
      let v4 = project(cx - R*0.5, 0, cz - R*0.866);
      let v5 = project(cx + R*0.5, 0, cz - R*0.866);

      if(v0 && v1 && v2 && v3 && v4 && v5) {
        let hash = (i * 73856093) ^ (j * 19349663);
        let pathStr = `M${v0.x.toFixed(1)},${v0.y.toFixed(1)} L${v1.x.toFixed(1)},${v1.y.toFixed(1)} L${v2.x.toFixed(1)},${v2.y.toFixed(1)} L${v3.x.toFixed(1)},${v3.y.toFixed(1)} L${v4.x.toFixed(1)},${v4.y.toFixed(1)} L${v5.x.toFixed(1)},${v5.y.toFixed(1)} Z`;
        if (hash & 1) yellowArr.push(pathStr);
        else jadeArr.push(pathStr);
      }
    }
  }
  floorJade.setAttribute('d', jadeArr.join(' '));
  floorYellow.setAttribute('d', yellowArr.join(' '));

  let drawList = [];
  for(let e of enemies) drawList.push({type: 0, z: e.z, data: e});
  for(let b of bullets) drawList.push({type: 1, z: b.z, data: b});
  for(let p of particles) drawList.push({type: 2, z: p.z, data: p});
  drawList.sort((a, b) => b.z - a.z);

  let pathIdx = 0, circleIdx = 0, rectIdx = 0;

  let invaderPattern = [
    "00100100", 
    "00010100", 
    "00111100", 
    "01100110", 
    "11111111", 
    "10111101", 
    "10100101", 
    "00011000"
  ];

  for(let item of drawList) {
    if(item.type === 0) { 
      let e = item.data;
      let s = 0.4; 

      let vIdx = 0;
      for(let r=0; r<9; r++) {
        for(let c=0; c<9; c++) {
          let lx = e.x + (c - 4) * s;
          let ly = e.y + (4 - r) * s;
          // FIX: Correct Front (vf) and Back (vb) Z coordinates to fix missing front panels
          let vf = project(lx, ly, e.z - s);
          let vb = project(lx, ly, e.z + s);
          if(vf && vb) {
            invaderVerts[vIdx].fx = vf.x; invaderVerts[vIdx].fy = vf.y; invaderVerts[vIdx].fz = vf.z;
            invaderVerts[vIdx].bx = vb.x; invaderVerts[vIdx].by = vb.y; invaderVerts[vIdx].bz = vb.z;
          } else {
            invaderVerts[vIdx].fz = -1; 
          }
          vIdx++;
        }
      }

      let backArr = [], bottomArr = [], topArr = [], leftArr = [], rightArr = [], frontArr = [], eyesArr = [];
      for(let r=0; r<8; r++) {
        for(let c=0; c<8; c++) {
          if(invaderPattern[r][c] === '1') {
            let tl = invaderVerts[r*9+c];
            let tr = invaderVerts[r*9+c+1];
            let bl = invaderVerts[(r+1)*9+c];
            let br = invaderVerts[(r+1)*9+c+1];

            if(tl.fz < 0 || tr.fz < 0 || bl.fz < 0 || br.fz < 0) continue;

            let isEye = (r === 0 && (c === 2 || c === 5));
            let pStr = `M${tl.fx},${tl.fy} L${tr.fx},${tr.fy} L${br.fx},${br.fy} L${bl.fx},${bl.fy} Z`;

            // Draw Front Panel!
            if(isEye) eyesArr.push(pStr);
            else frontArr.push(pStr);

            // Side Panels Culling & Generation
            let hasTop = (r > 0 && invaderPattern[r-1][c] === '1');
            let hasBottom = (r < 7 && invaderPattern[r+1][c] === '1');
            let hasLeft = (c > 0 && invaderPattern[r][c-1] === '1');
            let hasRight = (c < 7 && invaderPattern[r][c+1] === '1');

            if(!hasTop) topArr.push(`M${tl.fx},${tl.fy} L${tr.fx},${tr.fy} L${tr.bx},${tr.by} L${tl.bx},${tl.by} Z`);
            if(!hasBottom) bottomArr.push(`M${bl.fx},${bl.fy} L${br.fx},${br.fy} L${br.bx},${br.by} L${bl.bx},${bl.by} Z`);
            if(!hasLeft) leftArr.push(`M${tl.fx},${tl.fy} L${bl.fx},${bl.fy} L${bl.bx},${bl.by} L${tl.bx},${tl.by} Z`);
            if(!hasRight) rightArr.push(`M${tr.fx},${tr.fy} L${br.fx},${br.fy} L${br.bx},${br.by} L${tr.bx},${tr.by} Z`);
          }
        }
      }

      // Correct Draw Order to guarantee solid cubes (Back to Front)
      if(backArr.length) { let p = getPoolEl(pathPool, 'path', scene, pathIdx++); p.setAttribute('d', backArr.join(' ')); p.setAttribute('fill', '#2d5a36'); p.setAttribute('stroke', 'none'); }
      if(bottomArr.length) { let p = getPoolEl(pathPool, 'path', scene, pathIdx++); p.setAttribute('d', bottomArr.join(' ')); p.setAttribute('fill', '#5BA66B'); p.setAttribute('stroke', '#003300'); p.setAttribute('stroke-width', '0.5'); p.setAttribute('stroke-linejoin', 'round'); }
      if(topArr.length) { let p = getPoolEl(pathPool, 'path', scene, pathIdx++); p.setAttribute('d', topArr.join(' ')); p.setAttribute('fill', '#B3FFB3'); p.setAttribute('stroke', '#003300'); p.setAttribute('stroke-width', '0.5'); p.setAttribute('stroke-linejoin', 'round'); }
      if(leftArr.length) { let p = getPoolEl(pathPool, 'path', scene, pathIdx++); p.setAttribute('d', leftArr.join(' ')); p.setAttribute('fill', '#76C786'); p.setAttribute('stroke', '#003300'); p.setAttribute('stroke-width', '0.5'); p.setAttribute('stroke-linejoin', 'round'); }
      if(rightArr.length) { let p = getPoolEl(pathPool, 'path', scene, pathIdx++); p.setAttribute('d', rightArr.join(' ')); p.setAttribute('fill', '#76C786'); p.setAttribute('stroke', '#003300'); p.setAttribute('stroke-width', '0.5'); p.setAttribute('stroke-linejoin', 'round'); }
      if(frontArr.length) { let p = getPoolEl(pathPool, 'path', scene, pathIdx++); p.setAttribute('d', frontArr.join(' ')); p.setAttribute('fill', '#90EE90'); p.setAttribute('stroke', '#003300'); p.setAttribute('stroke-width', '0.5'); p.setAttribute('stroke-linejoin', 'round'); }
      if(eyesArr.length) { let p = getPoolEl(pathPool, 'path', scene, pathIdx++); p.setAttribute('d', eyesArr.join(' ')); p.setAttribute('fill', '#FF0000'); p.setAttribute('stroke', 'none'); }

    } else if(item.type === 1) { 
      let b = item.data;
      let v = project(b.x, b.y, b.z);
      if(v) {
        let el = getPoolEl(circlePool, 'circle', scene, circleIdx++);
        el.setAttribute('cx', v.x); el.setAttribute('cy', v.y);
        el.setAttribute('r', (0.3 * 400 / v.z)); el.setAttribute('fill', b.color);
      }
    } else if(item.type === 2) { 
      let pt = item.data;
      let v = project(pt.x, pt.y, pt.z);
      if(v) {
        let el = getPoolEl(rectPool, 'rect', scene, rectIdx++);
        let s = (0.15 * 400 / v.z);
        el.setAttribute('x', v.x - s/2); el.setAttribute('y', v.y - s/2);
        el.setAttribute('width', s); el.setAttribute('height', s);
        el.setAttribute('fill', pt.color); el.setAttribute('opacity', pt.life/30);
      }
    }
  }

  for (let i = pathIdx; i < pathPool.length; i++) pathPool[i].style.display = 'none';
  for (let i = circleIdx; i < circlePool.length; i++) circlePool[i].style.display = 'none';
  for (let i = rectIdx; i < rectPool.length; i++) rectPool[i].style.display = 'none';

  // --- ATON RA Character Rendering (Anthropomorphic Human IK) ---
  let svgStr = "";
  if (isThirdPerson) {
    let charProj = project(player.x, 0, player.z); 
    if (charProj) {
      let s = Math.min(400 / charProj.z, 10) * 0.133; 
      let baseX = charProj.x;
      let baseY = charProj.y;

      let wp = player.walkPhase;
      let walkMod = player.speed > 0.01 ? 1.0 : 0.1;
      let fwd = player.fwd || 0;
      let strafe = player.strafe || 0;

      // Anthropomorphic Proportions
      let strideLen = 12 * s * (Math.abs(fwd) + Math.abs(strafe));
      if(strideLen > 15 * s) strideLen = 15 * s;
      let lift = 12 * s;

      let phaseL = wp;
      let phaseR = wp + Math.PI;

      // Hip and Shoulder anchors
      let hipLX = baseX - 6 * s;
      let hipRX = baseX + 6 * s;
      let hipY = baseY - 20 * s;

      let shoulderLX = baseX - 12 * s;
      let shoulderRX = baseX + 12 * s;
      let shoulderY = baseY - 35 * s;

      // IK Targets for Legs
      let footLX = hipLX + Math.sin(phaseL) * strideLen;
      let footLY = baseY + Math.cos(phaseL) * strideLen * 0.5;
      let footLiftL = Math.max(0, Math.cos(phaseL)) * lift;
      let legL = ik2D(hipLX, hipY, 14 * s, 14 * s, footLX, footLY - footLiftL, -1);

      let footRX = hipRX + Math.sin(phaseR) * strideLen;
      let footRY = baseY + Math.cos(phaseR) * strideLen * 0.5;
      let footLiftR = Math.max(0, Math.cos(phaseR)) * lift;
      let legR = ik2D(hipRX, hipY, 14 * s, 14 * s, footRX, footRY - footLiftR, 1);

      // IK Targets for Arms (Opposite Phase)
      let handLX = shoulderLX - Math.sin(phaseL) * strideLen * 0.5;
      let handLY = baseY - 15 * s - Math.cos(phaseL) * strideLen * 0.25;
      let handLiftL = Math.max(0, Math.cos(phaseL)) * lift * 0.5;
      let armL = ik2D(shoulderLX, shoulderY, 12 * s, 12 * s, handLX, handLY - handLiftL, 1);

      let handRX = shoulderRX - Math.sin(phaseR) * strideLen * 0.5;
      let handRY = baseY - 15 * s - Math.cos(phaseR) * strideLen * 0.25;
      let handLiftR = Math.max(0, Math.cos(phaseR)) * lift * 0.5;
      let armR = ik2D(shoulderRX, shoulderY, 12 * s, 12 * s, handRX, handRY - handLiftR, -1);

      let bob = Math.abs(Math.sin(wp * 2)) * 2 * s * walkMod;
      let floatY = -bob;

      // Draw Back Leg (Solid Blocky Rects + Spherical Joints)
      svgStr += makeLimb(hipRX, hipY + floatY, legR.jx, legR.jy + floatY, 6*s, "#111");
      svgStr += makeLimb(legR.jx, legR.jy + floatY, legR.tx, legR.ty + floatY, 6*s, "#111");
      svgStr += `<circle cx="${legR.jx}" cy="${legR.jy + floatY}" r="${5*s}" fill="url(#sphereGrad)" />`;
      svgStr += `<ellipse cx="${legR.tx}" cy="${legR.ty + 2*s + floatY}" rx="${8*s}" ry="${4*s}" fill="#000" />`;

      // Draw Back Arm
      svgStr += makeLimb(shoulderRX, shoulderY + floatY, armR.jx, armR.jy + floatY, 5*s, "#111");
      svgStr += makeLimb(armR.jx, armR.jy + floatY, armR.tx, armR.ty + floatY, 5*s, "#111");
      svgStr += `<circle cx="${armR.jx}" cy="${armR.jy + floatY}" r="${4*s}" fill="url(#sphereGrad)" />`;
      svgStr += `<circle cx="${armR.tx}" cy="${armR.ty + floatY}" r="${5*s}" fill="url(#sphereGrad)" />`;

      // Draw Big Floating Torso Sphere
      svgStr += `<circle cx="${baseX}" cy="${baseY - 30 * s + floatY}" r="${15 * s}" fill="url(#sphereGrad)" />`;

      // Draw Floating Head Sphere
      svgStr += `<circle cx="${baseX}" cy="${baseY - 55 * s + floatY}" r="${8 * s}" fill="url(#sphereGrad)" />`;
      svgStr += `<circle cx="${baseX}" cy="${baseY - 62 * s + floatY}" r="${4 * s}" fill="url(#redSphereGrad)" />`;

      // Draw Front Leg
      svgStr += makeLimb(hipLX, hipY + floatY, legL.jx, legL.jy + floatY, 6*s, "#111");
      svgStr += makeLimb(legL.jx, legL.jy + floatY, legL.tx, legL.ty + floatY, 6*s, "#111");
      svgStr += `<circle cx="${legL.jx}" cy="${legL.jy + floatY}" r="${5*s}" fill="url(#sphereGrad)" />`;
      svgStr += `<ellipse cx="${legL.tx}" cy="${legL.ty + 2*s + floatY}" rx="${8*s}" ry="${4*s}" fill="#000" />`;

      // Draw Front Arm
      svgStr += makeLimb(shoulderLX, shoulderY + floatY, armL.jx, armL.jy + floatY, 5*s, "#111");
      svgStr += makeLimb(armL.jx, armL.jy + floatY, armL.tx, armL.ty + floatY, 5*s, "#111");
      svgStr += `<circle cx="${armL.jx}" cy="${armL.jy + floatY}" r="${4*s}" fill="url(#sphereGrad)" />`;
      svgStr += `<circle cx="${armL.tx}" cy="${armL.ty + floatY}" r="${5*s}" fill="url(#sphereGrad)" />`;
    }
  } else {
    // First Person Gun
    svgStr += `<rect x="550" y="400" width="150" height="40" fill="#222" rx="10" transform="rotate(-15 600 420)" />`;
    svgStr += `<rect x="620" y="380" width="30" height="50" fill="#111" rx="5" transform="rotate(-15 600 420)" />`;
    if (fireFlash > 0) {
      svgStr += `<circle cx="650" cy="380" r="${fireFlash * 4}" fill="orange" opacity="${fireFlash / 10}" />`;
      svgStr += `<circle cx="650" cy="380" r="${fireFlash * 2}" fill="yellow" opacity="${fireFlash / 5}" />`;
    }
    svgStr += `<line x1="395" y1="300" x2="405" y2="300" stroke="white" stroke-width="2" />`;
    svgStr += `<line x1="400" y1="295" x2="400" y2="305" stroke="white" stroke-width="2" />`;
  }
  atonRaG.innerHTML = svgStr;
}
